from .paths import TemplatesFinder, PathsProvider
from .strategy import CommonStrategy
from .archive import AddonsExtractor, HeatTemplatesExtractor
from .facades import TemplatesExtractFacade, TemplatesExtractRCP2Facade
from .templates import Templates5G18A_RCP20


class HeatTemplateFactory(object):

    """Create HeatTemplates instance using template files."""

    def __init__(self, serializer, heat_template_cls):
        self.__serializer = serializer
        self.__template_cls = heat_template_cls

    def create(self, yaml, env=None):
        """
        Load template files and create `HeatTemplate` instance.

        :yaml: path to file containing definitions
        :env: path to file containing variables
        """
        yaml = self.__serializer.load(yaml)
        env = self.__serializer.load(env) if env else None
        heat_template = self.__template_cls(yaml=yaml, env=env)
        return heat_template


class ExtractorFactory(object):
    def __init__(self, template_dispatcher, template_cache, templ_recognizer, variant='site_solution'):
        self._templ_dispatcher = template_dispatcher
        self._templ_cache = template_cache
        self._templ_recognizer = templ_recognizer
        self._extract_strategy = CommonStrategy(AddonsExtractor(),
                                                HeatTemplatesExtractor(),
                                                PathsProvider(variant))

    def create(self, addons):
        templ_cls = self._templ_dispatcher.get_cls_by_addons(addons)
        templ_def = self._templ_cache.get(templ_cls)
        finder = TemplatesFinder(templ_def, self._templ_recognizer)
        extractor_cls = self._get_extract_facade_cls(templ_cls)
        return extractor_cls(self._extract_strategy, finder)

    def _get_extract_facade_cls(self, templ_cls):
        return TemplatesExtractRCP2Facade if templ_cls == Templates5G18A_RCP20\
            else TemplatesExtractFacade
